/* ==UserStyle==
@name Roblox Tactical Wallpaper
@namespace RAUTF-03
@version 1.0
@description Custom background + UI tweaks for Roblox site only
@match *://*.roblox.com/*
==/UserStyle== */

/* === Custom Wallpaper Setup === */
body {
  background: url("https://i.imgur.com/YOUR_IMAGE_LINK.jpg") no-repeat center center fixed !important;
  background-size: cover !important;
  color: #e0e0e0 !important;
}

/* Optional transparency for UI elements */
div, section, header, footer, main {
  background-color: rgba(0, 0, 0, 0.3) !important;
  backdrop-filter: blur(3px);
}

/* Buttons + Links */
a, button {
  color: #00ffcc !important;
  border-color: #00ffcc !important;
}

a:hover, button:hover {
  background-color: rgba(0, 255, 204, 0.1) !important;
}

/* Optional: make text pop */
h1, h2, h3, h4, h5, h6 {
  color: #ffffff !important;
  text-shadow: 0 0 4px #00ffcc;
}
